package main
import("context";"fmt";"os";"github.com/jackc/pgx/v5/pgxpool")
func main(){c:=context.Background();p,e:=pgxpool.New(c,os.Getenv("DATABASE_URL"));if e!=nil{panic(e)};defer p.Close(); rows,e:=p.Query(c,`SELECT r.id,r.stream_id,coalesce(r.preferred_relay_group_id,0),coalesce(a.server_id,''),coalesce(a.execution_class,''),r.status FROM recordings r LEFT JOIN recording_assignments a ON a.stream_id=r.stream_id WHERE r.account_id=47 AND r.status='active' AND (r.preferred_relay_group_id IN (2,3,4) OR a.server_id ILIKE '%mini%') ORDER BY r.id`);if e!=nil{panic(e)};defer rows.Close();for rows.Next(){var id,sid,grp int64;var n,ec,st string;if e:=rows.Scan(&id,&sid,&grp,&n,&ec,&st);e!=nil{panic(e)};fmt.Printf("recording=%d stream=%d group=%d server=%s class=%s status=%s\n",id,sid,grp,n,ec,st)}}
